base.expression:
// extract out the base rating contribution to the base stat to get the true base (baseAdj)
const base = GetStat(GetOwner(), $#10516612381411111:6064628617716498442$);
const baseRating = GetStat(GetInstigator(), $#10516612381411111:6064628617716695054$);
const baseCoeff = EvalE($#10516612381411112:6064633883782021221$);
const baseAdj = base - baseRating / (baseRating + baseCoeff);

// calculate total rating including the base rating but reduced by the coefficient quotient
const coeff = EvalE($#10516612381411112:6064630400882507797$);
const rating = baseRating * coeff/baseCoeff + GetStat(GetInstigator(), $#10516612381411111:109183605036676$);

// calc final stat value
const stamEvaMult = EvalFormula($#10516612381411113:6064631902456119305$);
(baseAdj + rating / (rating + coeff)) * stamEvaMult
